		private void Initialization(short type)
		{
			SizeExchangerIsEnabled = true;
			SpecifyExcahngerGeometryIsEnabled = false;
			SetRadioButton(type);
			SizeGeometryMethod = SizeGeometryMethodEnum.InputGeometry;
			SizeInteractiveMethod = SizeInteractiveMethodEnum.SizeInteractively;
			SelectedExchangerType = type;
			SelectedConvertMethod = 1;
		}

		private void SetRadioButton(short type)
		{
			_typeRadBtnList = new List<System.Windows.Controls.RadioButton>();
			_typeRadBtnList.Add(ExchangerType_1);
			_typeRadBtnList.Add(ExchangerType_2);
			_typeRadBtnList.Add(ExchangerType_3);
			_typeRadBtnList.Add(ExchangerType_4);
			_typeRadBtnList.Add(ExchangerType_5);
			_typeRadBtnList[type - 1].IsChecked = true;
		}

		private void SizeGeometryMethodCallBack(object args)
		{
