		private void ConvertMethodCatalog(object args)
		{
			if (int.TryParse(args.ToString(), out var result))
			{
				_ConvertMethodCatalogValue = (ConvertMethodCatalogEnum)result;
				if (_ConvertMethodCatalogValue == ConvertMethodCatalogEnum.SizeExchchanger)
				{
					SizeExchangerIsEnabled = true;
					SpecifyExcahngerGeometryIsEnabled = false;
				}
				else if (_ConvertMethodCatalogValue == ConvertMethodCatalogEnum.SpecifyExcahngerGeometry)
				{
					SizeExchangerIsEnabled = false;
					SpecifyExcahngerGeometryIsEnabled = true;
				}
				SelectedConvertMethod = result;
				((RelayActionCommand)Convert).RaiseCanExecuteChanged();
			}
		}

		private void ExcahgnerTypeConvert(object args)
		{
			if (int.TryParse(args.ToString(), out var result))
			{
				_ = (short)result;
				RadioButton_0_1.IsEnabled = true;
				SelectedExchangerType = result;
				((RelayActionCommand)Convert).RaiseCanExecuteChanged();
			}
		}

		private void SizeBrowseTemplate()
		{
			string strFilter = ApwnResources.FileType_EDR_Template_Files + " (*.edt)|*.edt| " + ApwnResources.FileType_EDR_Input_Files + " (*.edr)|*.edr||";
			string text = OpenFileDlg(strFilter);
			if (text != string.Empty)
			{
				TemplateFileName = text;
			}
		}

		private bool SizeTemplateCanBrowse()
		{
			return SizingMethod == SizeMethodEnum.SizeInteractiveTemplate;
		}

		private void BrowseImportEdr()
		{
			string strFilter = "Exchanger Design and Rating Documents (*.EDR)|*.EDR||";
			string text = OpenFileDlg(strFilter);
			if (text != string.Empty)
			{
				EdrFileName = text;
			}
		}

		private bool ImportEdrCanBrowse()
		{
			return SizingMethod == SizeMethodEnum.ImportEDR;
		}

		private void DoConvert()
		{
			base.DialogResult = true;
			Close();
		}

		private bool CanConvert()
		{
			if (SizingMethod != SizeMethodEnum.SizeInteractively && SizingMethod != SizeMethodEnum.InputGeometry && (SizingMethod != SizeMethodEnum.SizeInteractiveTemplate || !File.Exists(_templateFileName) || (!_templateFileName.EndsWith(".EDT", StringComparison.OrdinalIgnoreCase) && !_templateFileName.EndsWith(".EDR", StringComparison.OrdinalIgnoreCase))))
			{
				if (SizingMethod == SizeMethodEnum.ImportEDR && File.Exists(_edrFileName))
				{
					return _edrFileName.EndsWith(".EDR", StringComparison.OrdinalIgnoreCase);
				}
				return false;
			}
			return true;
		}

		private string OpenFileDlg(string strFilter)
		{
			string result = string.Empty;
			try
			{
				System.Windows.Forms.OpenFileDialog openFileDialog = new System.Windows.Forms.OpenFileDialog();
				openFileDialog.Multiselect = false;
				openFileDialog.Filter = strFilter;
				openFileDialog.RestoreDirectory = true;
				if (openFileDialog.ShowDialog() == System.Windows.Forms.DialogResult.OK)
				{
					result = openFileDialog.FileName;
				}
				openFileDialog.Dispose();
			}
			catch (Exception)
			{
			}
			return result;
		}

