		private void cmdBrowse1_CommandExecute(object parameter)
		{
			string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.TEMPL_FILE", "value"));
			if (!string.IsNullOrEmpty(text))
			{
				int num = text.LastIndexOf("\\");
				text = ((num == -1) ? Directory.GetCurrentDirectory() : text.Substring(0, num));
			}
			else
			{
				text = MMHeatx_setup_sizerigorous_ViewModel.getTemplateDir();
			}
			System.Windows.Forms.OpenFileDialog openFileDialog = new System.Windows.Forms.OpenFileDialog();
			openFileDialog.InitialDirectory = text;
			openFileDialog.RestoreDirectory = true;
			openFileDialog.Title = Resources.MMHeatx_Hetran_File_ViewModel_SelectEDRTemplFile;
			openFileDialog.Filter = ApwnResources.FileType_EDR_Template_Files + " (*.edt)|*.edt| " + ApwnResources.FileType_EDR_Input_Files + " (*.edr)|*.edr";
			openFileDialog.RestoreDirectory = true;
			if (openFileDialog.ShowDialog() == DialogResult.OK)
			{
				string fileName = openFileDialog.FileName;
				if (!string.IsNullOrEmpty(fileName) && fileName.Substring(fileName.LastIndexOf(".") + 1) == "EDT")
				{
					string text2 = fileName.Substring(0, fileName.LastIndexOf("\\"));
					if (!string.IsNullOrEmpty(text2))
					{
						MMHeatx_setup_sizerigorous_ViewModel.setTemplateDir(text2);
					}
				}
				if (!string.IsNullOrEmpty(fileName))
				{
					stripdir(fileName, Directory.GetCurrentDirectory(), "TEMPLATE");
				}
			}
			openFileDialog.Dispose();
		}

		private void cmdBrowse2_CommandExecute(object parameter)
		{
			string currentDirectory = Directory.GetCurrentDirectory();
			System.Windows.Forms.OpenFileDialog openFileDialog = new System.Windows.Forms.OpenFileDialog();
			openFileDialog.RestoreDirectory = true;
			openFileDialog.Title = Resources.MMHeatx_Hetran_File_ViewModel_SelectEDRInputFile;
			openFileDialog.Filter = ApwnResources.FileType_EDR_Input_Files + " (*.edr)|*.edr||";
			openFileDialog.RestoreDirectory = true;
			openFileDialog.ShowDialog();
			string fileName = openFileDialog.FileName;
			if (fileName != null && fileName.Length > 0)
			{
				stripdir(fileName, currentDirectory, "INPUT");
			}
			openFileDialog.Dispose();
		}

		private void stripdir(string strFileName, string strDirectory, string typ)
		{
			if (strFileName.Substring(0, strFileName.LastIndexOf("\\")).ToUpper() == strDirectory.ToUpper())
			{
				strFileName = strFileName.Substring(strFileName.LastIndexOf("\\") + 1);
			}
			if (typ == "INPUT")
			{
				ExpandDataPathAndSet("@main.Input.INPUT_FILE", "value", strFileName);
			}
			else if (typ == "TEMPLATE")
			{
				ExpandDataPathAndSet("@main.Input.TEMPL_FILE", "value", strFileName);
			}
		}

		private void cmdConvert_CommandExecute(object parameter)
		{
			string path = ExpandDataPath("@main.Input.MODE");
			string text = CxsConverter.ValueToString(base.ResolvedCxsProvider.BatchGet(path, "value", null));
			string parameter2 = "";
			string modelName = "";
			switch (text)
			{
			case "TASCPLUS-RIG":
			case "KETTLE":
			case "THERMOSIPHON":
				parameter2 = "Size Shell&Tube";
				modelName = "Tasc";
				break;
			case "ACOL-RIG":
				parameter2 = "Size AirCooled";
				modelName = "Acol";
				break;
			case "APLE-RIG":
				parameter2 = "Size Plate";
				modelName = "Aple";
				break;
			}
			CloseForm();
			string path2 = ExpandDataPath("@main.Input.CONV_METHOD");
			string text2 = CxsConverter.ValueToString(base.ResolvedCxsProvider.BatchGet(path2, "value", null));
			if (text2 == "SIZE")
			{
				string templateFilePath = "";
				string path3 = ExpandDataPath("@main.Input.SIZE_TEMPL");
				text = CxsConverter.ValueToString(base.ResolvedCxsProvider.BatchGet(path3, "value", null));
				if (text == "YES")
				{
					string path4 = ExpandDataPath("@main.Input.TEMPL_FILE");
					templateFilePath = CxsConverter.ValueToString(base.ResolvedCxsProvider.BatchGet(path4, "value", null));
				}
				ExecuteSize(parameter2, modelName, templateFilePath);
			}
			else if (text2 == "GEOMETRY")
			{
				SpecifingGeometry(parameter2, modelName);
			}
		}

		private void SpecifingGeometry(object parameter, string modelName)
		{
			ExpandDataPathAndSet("@main.Input.PROGRAM_MODE", "value", "0", "SIMULATION");
			string path = ExpandDataPath("@main.Input.GEOMETRY");
			if (CxsConverter.ValueToString(base.ResolvedCxsProvider.BatchGet(path, "value", null)) == "NO")
			{
				string text = ExpandDataPath("@main");
				text = text.Replace("Top.appModelV8.", "");
				text = text.Replace(".Data", "");
				GoToNode($"Simulation!{text}.{ApwnResources.BrowserEDRBrowser}", null, useNewTab: true);
			}
		}

		public void ExecuteSize(object parameter, string modelName, string templateFilePath)
		{
			if (_cxsCase == null)
			{
				_cxsCase = base.UnityContainer.Resolve<CxsCase>(Array.Empty<ResolverOverride>());
			}
			int? num = _cxsCase.InvokeAction("Top.appModelV8.Custom Actions", "EnableHxSize") as int?;
			bool flag = true;
			if (string.IsNullOrEmpty(parameter as string))
			{
				parameter = CxsConverter.ValueToString(ExpandDataPathAndGet("@main", "id"));
			}
			if (num > 0)
			{
				string message;
				switch (num)
				{
				case 1:
				case 3:
					message = ApwnResources.FailStartEDR;
					break;
				case 2:
					message = string.Format(ApwnResources.BadEDRVersion, _cxsCase.InvokeAction("Top.appModelV8.Custom Actions", "BjacAPver").ToString());
					break;
				case 4:
					message = ApwnResources.MMHeatx_setup_specif_SizeRigorous_Noresults;
					break;
				case 5:
					message = ApwnResources.MMHeatx_setup_specif_SizeRigorous_Ineo;
					break;
				default:
					message = ApwnResources.MMHeatx_setup_specif_SizeRigorous_Errorcheck;
					break;
				}
				ShowMessageBox(new ShowMessageBoxEventArgs
				{
					Message = message,
					Title = GetProductI18nName() + " - " + parameter.ToString()
				});
				flag = false;
			}
			else if (num < 0)
			{
				string message2 = "";
				if (num.HasValue && num == -1)
				{
					message2 = ApwnResources.MMHeatx_setup_specif_SizeRigorous_Inputchanged;
				}
				ShowMessageBoxEventArgs e = new ShowMessageBoxEventArgs
				{
					Title = GetProductI18nName() + " - " + parameter.ToString(),
					MsgBoxButton = MessageBoxButton.OKCancel
				};
				e.Message = message2;
				ShowMessageBox(e);
				if (e.DialogResult == MessageBoxResult.Cancel)
				{
					flag = false;
				}
			}
			if (flag)
			{
				DisplayForm(new DisplayFormEventArgs
				{
					HideCloseButton = true,
					FormProgId = "MMHeatx.MMHeatx_setup_sizeRigorous",
					LegacyFlags = 0,
					ShortName = string.Format(Resources.EDRConsoleHeader, parameter as string),
					CompleteDataPaths = new string[1] { "SIZERIG" },
					Parameters = 
					{
						{
							"TEMPLATE",
							(object)templateFilePath
						},
						{
							"MODEL",
							(object)modelName
						}
					}
				});
			}
		}

		protected override void OnSubPropertyDataChanged(CxvPropertyDeclaration pd, string subPropertyName)
		{
			if (pd.Name == "SizeOptionUsed" && subPropertyName == "Value")
			{
				UpdatePrompt();
			}
			base.OnSubPropertyDataChanged(pd, subPropertyName);
		}

		private void UpdatePrompt()
		{
			CxvBooleanPropertyData cxvBooleanPropertyData = SizeOptionUsed as CxvBooleanPropertyData;
			if (cxvBooleanPropertyData.Value.HasValue && cxvBooleanPropertyData.Value.Value)
			{
				ResolveUpdateParameter("p_SizeOptionPrompt", "");
			}
			else
			{
				ResolveUpdateParameter("p_SizeOptionPrompt", ExpandDataPathAndGet("@main.CC Nodes.SIZE4", "description"));
			}
		}

		protected override void OnUpdateData()
		{
			if (base.IsInitialUpdate)
			{
				bool? flag = CxsConverter.ValueToBoolean(ResolveParameter("ShowConvertionMethod"));
				bool? flag2 = CxsConverter.ValueToBoolean(ResolveParameter("ShowSizeExchanger"));
				bool? flag3 = CxsConverter.ValueToBoolean(ResolveParameter("ShowSpecifyExcahngerGeometry"));
				ButtonContent = ApwnResources.MMHeatx_Convert;
				if (flag3 == false)
				{
					ButtonContent = ApwnResources.MMHeatx_SizeExchanger_Size;
				}
				if (flag == true)
				{
					ExpandDataPathAndSet("@main.Input.CONV_METHOD", "value", "0", "SIZE");
				}
				else if (flag2 == true)
				{
					ExpandDataPathAndSet("@main.Input.CONV_METHOD", "value", "0", "SIZE");
					PlateRadioVisibility = Visibility.Visible;
				}
				else if (flag3 == true)
				{
					ExpandDataPathAndSet("@main.Input.CONV_METHOD", "value", "0", "GEOMETRY");
				}
			}
			base.OnUpdateData();
		}
	}
