		private void cmdBrowse_CommandExecute(object parameter)
		{
			string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.TEMPL_FILE", "value"));
			if (!string.IsNullOrEmpty(text))
			{
				int num = text.LastIndexOf("\\");
				text = ((num == -1) ? Directory.GetCurrentDirectory() : text.Substring(0, num));
			}
			else
			{
				text = MMHeatx_setup_sizerigorous_ViewModel.getTemplateDir();
			}
			System.Windows.Forms.OpenFileDialog openFileDialog = new System.Windows.Forms.OpenFileDialog();
			openFileDialog.InitialDirectory = text;
			openFileDialog.RestoreDirectory = true;
			openFileDialog.Title = Resources.MMHeatx_Hetran_File_ViewModel_SelectEDRTemplFile;
			openFileDialog.Filter = ApwnResources.FileType_EDR_Template_Files + " (*.edt)|*.edt| " + ApwnResources.FileType_EDR_Input_Files + " (*.edr)|*.edr";
			openFileDialog.RestoreDirectory = true;
			if (openFileDialog.ShowDialog() == DialogResult.OK)
			{
				string fileName = openFileDialog.FileName;
				if (!string.IsNullOrEmpty(fileName) && fileName.Substring(fileName.LastIndexOf(".") + 1) == "EDT")
				{
					string text2 = fileName.Substring(0, fileName.LastIndexOf("\\"));
					if (!string.IsNullOrEmpty(text2))
					{
						MMHeatx_setup_sizerigorous_ViewModel.setTemplateDir(text2);
					}
				}
				if (!string.IsNullOrEmpty(fileName))
				{
					stripdir(fileName, Directory.GetCurrentDirectory(), "TEMPLATE");
				}
			}
			openFileDialog.Dispose();
		}

		private void stripdir(string strFileName, string strDirectory, string typ)
		{
			if (strFileName.Substring(0, strFileName.LastIndexOf("\\")).ToUpper() == strDirectory.ToUpper())
			{
				strFileName = strFileName.Substring(strFileName.LastIndexOf("\\") + 1);
			}
			if (typ == "INPUT")
			{
				ExpandDataPathAndSet("@main.Input.INPUT_FILE", "value", strFileName);
			}
			else if (typ == "TEMPLATE")
			{
				ExpandDataPathAndSet("@main.Input.TEMPL_FILE", "value", strFileName);
			}
		}

		private void cmdSize_CommandExecute(object parameter)
		{
			string path = ExpandDataPath("@main.Input.MODE");
			string text = CxsConverter.ValueToString(base.ResolvedCxsProvider.BatchGet(path, "value", null));
			string parameter2 = "";
			if (!(text == "TASCPLUS-RIG"))
			{
				switch (text)
				{
				case "KETTLE":
				case "THERMOSIPHON":
					break;
				case "TASCPLUS-RIG":
					parameter2 = "Size AirCooled";
					goto IL_006c;
				default:
					goto IL_006c;
				}
			}
			parameter2 = "Size Shell&Tube";
			goto IL_006c;
			IL_006c:
			string templateFilePath = "";
			string path2 = ExpandDataPath("@main.Input.SIZE_TEMPL");
			text = CxsConverter.ValueToString(base.ResolvedCxsProvider.BatchGet(path2, "value", null));
			if (text == "YES")
			{
				string path3 = ExpandDataPath("@main.Input.TEMPL_FILE");
				templateFilePath = CxsConverter.ValueToString(base.ResolvedCxsProvider.BatchGet(path3, "value", null));
			}
			CloseForm();
			ExecuteSize(parameter2, "", templateFilePath);
		}

		public void ExecuteSize(object parameter, string modelName, string templateFilePath)
		{
			if (_cxsCase == null)
			{
				_cxsCase = base.UnityContainer.Resolve<CxsCase>(Array.Empty<ResolverOverride>());
			}
			int? num = _cxsCase.InvokeAction("Top.appModelV8.Custom Actions", "EnableHxSize") as int?;
			bool flag = true;
			if (string.IsNullOrEmpty(parameter as string))
			{
				parameter = CxsConverter.ValueToString(ExpandDataPathAndGet("@main", "id"));
			}
			if (num > 0)
			{
				string message;
				switch (num)
				{
				case 1:
				case 3:
					message = ApwnResources.FailStartEDR;
					break;
				case 2:
					message = string.Format(ApwnResources.BadEDRVersion, _cxsCase.InvokeAction("Top.appModelV8.Custom Actions", "BjacAPver").ToString());
					break;
				case 4:
					message = ApwnResources.MMHeatx_setup_specif_SizeRigorous_Noresults;
					break;
				case 5:
					message = ApwnResources.MMHeatx_setup_specif_SizeRigorous_Ineo;
					break;
				default:
					message = ApwnResources.MMHeatx_setup_specif_SizeRigorous_Errorcheck;
					break;
				}
				ShowMessageBox(new ShowMessageBoxEventArgs
				{
					Message = message,
					Title = GetProductI18nName() + " - " + parameter.ToString()
				});
				flag = false;
			}
			else if (num < 0)
			{
				string message2 = "";
				if (num.HasValue && num == -1)
				{
					message2 = ApwnResources.MMHeatx_setup_specif_SizeRigorous_Inputchanged;
				}
				ShowMessageBoxEventArgs e = new ShowMessageBoxEventArgs
				{
					Title = GetProductI18nName() + " - " + parameter.ToString(),
					MsgBoxButton = MessageBoxButton.OKCancel
				};
				e.Message = message2;
				ShowMessageBox(e);
				if (e.DialogResult == MessageBoxResult.Cancel)
				{
					flag = false;
				}
			}
			if (flag)
			{
				DisplayForm(new DisplayFormEventArgs
				{
					HideCloseButton = true,
					FormProgId = "MMHeatx.MMHeatx_setup_sizeRigorous",
					LegacyFlags = 0,
					ShortName = string.Format(Resources.EDRConsoleHeader, parameter as string),
					CompleteDataPaths = new string[1] { "SIZERIG" },
					Parameters = 
					{
						{
							"TEMPLATE",
							(object)templateFilePath
						},
						{
							"MODEL",
							(object)modelName
						}
					}
				});
			}
		}
	}
