		private void OnEDRConsole(ConsoleEventArgs args)
		{
			if (inSizing)
			{
				return;
			}
			if (args.Event == "Cancel")
			{
				if (objConsole != null && !string.IsNullOrEmpty(restoreTasc))
				{
					try
					{
						object obj = objConsole.GetType().InvokeMember("ATVService", BindingFlags.GetProperty, null, objConsole, new object[0]);
						obj?.GetType().InvokeMember("XMLApp", BindingFlags.SetProperty, null, obj, new object[1] { restoreTasc });
					}
					catch (Exception)
					{
					}
					restoreTasc = null;
				}
				if (bjacType != null && mBJAC != null)
				{
					try
					{
						bjacType.InvokeMember("RemoveDocument", BindingFlags.InvokeMethod, null, mBJAC, new object[1] { EDRFile });
					}
					catch (Exception)
					{
					}
				}
				if (File.Exists(EDRFile))
				{
					try
					{
						File.Delete(EDRFile);
					}
					catch (Exception)
					{
					}
				}
				CloseForm();
			}
			else if (args.Event == "ClosedConsole")
			{
				bool flag = true;
				string value = "SIMULATION";
				string value2 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.HOT_UTIL", "value"));
				if (string.IsNullOrEmpty(value2))
				{
					value2 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.COLD_UTIL", "value"));
				}
				if (!string.IsNullOrEmpty(value2))
				{
					string text = "";
					string message = "";
					if (model == "Tasc")
					{
						if (CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.PROGRAM_MODE", "value")).ToUpper() == "SIMULATION")
						{
							text = Resources.MMHeatx_setup_specif_ViewModel__CxvMultiMapOption_Display_Size_EDR_Shell_Tube;
							message = ApwnResources.MMHeatx_setup_size_utilityprompt_simulation;
							flag = false;
						}
						else
						{
							value = "RATING";
						}
					}
					else if (model == "Acol")
					{
						text = Resources.MMHeatx_setup_specif_ViewModel__CxvMultiMapOption_Display_Size_EDR_AirCooled;
						message = ApwnResources.MMHeatx_setup_size_utilityprompt;
						flag = false;
					}
					if (!flag)
					{
						ShowMessageBox(new ShowMessageBoxEventArgs
						{
							Message = message,
							Title = GetProductI18nName() + " - " + text
						});
					}
				}
				if (!flag)
				{
					return;
				}
				try
				{
					if (bjacType != null && mBJAC != null)
					{
						bjacType.InvokeMember("FileExport", BindingFlags.InvokeMethod, null, mBJAC, new object[2] { EDRFile, EDRFile });
					}
				}
				catch (Exception)
				{
				}
				ExpandDataPathAndSet("@main.Input.PROGRAM_MODE", "value", value);
				object pScalars = null;
				string value3 = EDRFile;
				string caseWorkingDirectory = _cxsCase.CaseWorkingDirectory;
				string text2 = EDRFile.Substring(EDRFile.LastIndexOf("\\") + 1);
				if (EDRFile.StartsWith(caseWorkingDirectory))
				{
					value3 = text2;
				}
				ExpandDataPathAndSet("@main.Input.INPUT_FILE", "value", value3);
				string text3 = CxsConverter.ValueToString(ResolveParameter("MODETypeAplus"));
				if (!string.IsNullOrEmpty(text3))
				{
					ExpandDataPathAndSet("@main.Input.MODE", "value", text3);
				}
				else if (model == "Tasc")
				{
					ExpandDataPathAndSet("@main.Input.MODE", "value", "TASCPLUS-RIG");
				}
				else if (model == "Acol")
				{
					ExpandDataPathAndSet("@main.Input.MODE", "value", "ACOL-RIG");
				}
				if (model == "Tasc" || model == "Acol")
				{
					string text4 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.HSHELL_TUBE", "value"));
					string aTVar = SizingHelper.getATVar(objConsole, ref pScalars, "LocFluidHS");
					if (aTVar != null)
					{
						string text5 = ((aTVar == "1") ? "SHELL" : "TUBE");
						if (text5 != text4)
						{
							ExpandDataPathAndSet("@main.Input.HSHELL_TUBE", "value", text5);
						}
					}
				}
				if (!string.IsNullOrEmpty(text3) && text3 == "THERMOSIPHON")
				{
					ExpandDataPathAndSet("@main.Input.CIRC_TYPE", "value", "FIND-FLOW");
					double? num = CxsConverter.ValueToDouble(ExpandDataPathAndGet("@main.Input.COLD_COL_PRS", "value"));
					string text6 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.COLD_COL_PRS", "uom"));
					double aConvert;
					double bConvert;
					if (num.HasValue)
					{
						aConvert = GetAConvert(ExpandDataPath("@main.Input.COLD_COL_PRS"));
						bConvert = GetBConvert(ExpandDataPath("@main.Input.COLD_COL_PRS"));
					}
					else
					{
						text6 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Output.COLDINP", "uom"));
						num = CxsConverter.ValueToDouble(ExpandDataPathAndGet("@main.Output.COLDINP", "value"));
						aConvert = GetAConvert(ExpandDataPath("@main.Output.COLDINP"));
						bConvert = GetBConvert(ExpandDataPath("@main.Output.COLDINP"));
					}
					if (!string.IsNullOrEmpty(text6) && num.HasValue && aConvert != 0.0)
					{
						double num2 = (num.Value - bConvert) / aConvert;
						double num3 = double.Parse(SizingHelper.getATVar(objConsole, ref pScalars, "PresOperAtLiqSurfCS"), CultureInfo.InvariantCulture);
						if ((num2 - num3) / num3 > 0.01 || (num2 - num3) / num3 < -0.01)
						{
							num = num3 * aConvert + bConvert;
							ExpandDataPathAndSet("@main.Input.COLD_COL_PRS", "value", text6, num);
						}
					}
				}
				if (_cxsCase.CaseFileName.ToUpper().EndsWith(".APWZ"))
				{
					string caseWorkingDirectory2 = _cxsCase.CaseWorkingDirectory;
					caseWorkingDirectory2 = caseWorkingDirectory2.Substring(0, caseWorkingDirectory2.LastIndexOf("\\"));
					caseWorkingDirectory2 = caseWorkingDirectory2 + "\\" + _cxsCase.CaseFileName + "!" + EDRFile.Substring(EDRFile.LastIndexOf("\\") + 1);
					File.Copy(EDRFile, caseWorkingDirectory2, overwrite: true);
				}
				if (pScalars != null)
				{
					pScalars = null;
				}
				CloseForm();
			}
			else if (args.Event == "Size")
			{
				if (factory == null)
				{
					factory = base.UnityContainer.Resolve<IExchangerDesignFactory>(Array.Empty<ResolverOverride>());
				}
				if (factory != null)
				{
					inSizing = true;
					try
					{
						IExchangerDesignProvider exchangerDesignProvider = base.UnityContainer.Resolve<IExchangerDesignProvider>(Array.Empty<ResolverOverride>());
						compatVersion = exchangerDesignProvider.CompatibleExchangerVersionString;
						base.UnityContainer.RegisterInstance((IExchangerDesignProvider)this, (LifetimeManager)new ExternallyControlledLifetimeManager());
						FrameworkElement frameworkElement = factory.CreateUserControl("Progress", model, ExpandDataPath("@main"), runOnLoad: true);
						if (exchangerDesignProvider != null)
						{
							base.UnityContainer.RegisterInstance(exchangerDesignProvider, new ExternallyControlledLifetimeManager());
						}
						if (frameworkElement != null)
						{
							Window window = new Window();
							window.Title = $"EDR Sizing - Optimizing {BlkNameWithFullPath}";
							window.SizeToContent = SizeToContent.WidthAndHeight;
							window.WindowStartupLocation = WindowStartupLocation.CenterScreen;
							window.Owner = Window.GetWindow(base.View as DependencyObject);
							window.Content = frameworkElement;
							window.ShowDialog();
						}
					}
					catch (Exception)
					{
					}
				}
				inSizing = false;
			}
			else if (args.Event == "Save")
			{
				System.Windows.Forms.SaveFileDialog saveFileDialog = new System.Windows.Forms.SaveFileDialog();
				saveFileDialog.AddExtension = true;
				saveFileDialog.DefaultExt = "edr";
				saveFileDialog.Filter = ApwnResources.SaveEDRFilter;
				saveFileDialog.Title = ApwnResources.SaveEDRTitle;
				saveFileDialog.InitialDirectory = Directory.GetCurrentDirectory();
				saveFileDialog.CheckPathExists = true;
				saveFileDialog.RestoreDirectory = true;
				if (bjacType != null && mBJAC != null && saveFileDialog.ShowDialog() == DialogResult.OK)
				{
					try
					{
						bjacType.InvokeMember("FileExport", BindingFlags.InvokeMethod, null, mBJAC, new object[2] { EDRFile, saveFileDialog.FileName });
					}
					catch (Exception)
					{
					}
				}
			}
			else
			{
				_ = args.Event == "Import";
			}
		}

