		private string getTemplete()
		{
			System.Windows.Forms.OpenFileDialog openFileDialog = new System.Windows.Forms.OpenFileDialog();
			openFileDialog.RestoreDirectory = true;
			openFileDialog.InitialDirectory = getTemplateDir();
			openFileDialog.Title = Resources.MMHeatx_SizeRigorous_SelectEDTFile;
			openFileDialog.Filter = ApwnResources.FileType_EDR_Template_Files + " (*.edt)|*.edt|" + ApwnResources.FileType_EDR_Input_Files + " (*.edr)|*.edr";
			openFileDialog.RestoreDirectory = true;
			string text = "";
			if (openFileDialog.ShowDialog() == DialogResult.OK)
			{
				text = openFileDialog.FileName;
				string text2 = "";
				if (!string.IsNullOrEmpty(text) && text.Substring(text.LastIndexOf(".") + 1) == "EDT")
				{
					text2 = text.Substring(0, text.LastIndexOf("\\"));
					if (!string.IsNullOrEmpty(text2))
					{
						setTemplateDir(text2);
					}
				}
			}
			openFileDialog.Dispose();
			return text;
		}

		public static string getTemplateDir()
		{
			RegistryKey currentUser = Registry.CurrentUser;
			currentUser = currentUser.OpenSubKey("Software\\AspenTech\\B-JAC\\Common\\Settings", writable: false);
			if (currentUser == null)
			{
				return Directory.GetCurrentDirectory();
			}
			string name = "DocTempFolder";
			object value = currentUser.GetValue(name);
			if (value == null)
			{
				return Directory.GetCurrentDirectory();
			}
			return value.ToString();
		}

		public static void setTemplateDir(string newTemplateDir)
		{
			if (!string.IsNullOrEmpty(newTemplateDir) && (!(newTemplateDir.ToUpper() == getTemplateDir().ToUpper()) || !(newTemplateDir.ToUpper() != Directory.GetCurrentDirectory().ToUpper())))
			{
				RegistryKey currentUser = Registry.CurrentUser;
				RegistryKey registryKey = currentUser.OpenSubKey("Software\\AspenTech\\B-JAC\\Common\\Settings", writable: true);
				if (registryKey == null)
				{
					registryKey = currentUser.CreateSubKey("Software\\AspenTech\\B-JAC\\Common\\Settings");
				}
				string name = "DocTempFolder";
				registryKey.SetValue(name, newTemplateDir);
			}
		}

		public IntPtr GetATVInterface(string objectType, string objectKey)
		{
			if (objectKey != ExpandDataPath("@main"))
			{
				return IntPtr.Zero;
			}
			if (objConsole != null)
			{
				return Marshal.GetIDispatchForObject(objConsole);
			}
			IAplusBJACWrapper aplusBJACWrapper = base.UnityContainer.Resolve<IAplusBJACWrapper>(Array.Empty<ResolverOverride>());
			mBJAC = aplusBJACWrapper.BJACApp;
			if (mBJAC == null)
			{
				return IntPtr.Zero;
			}
			bjacType = aplusBJACWrapper.ComType;
			string text = CxsConverter.ValueToString(ResolveParameter("MODETypeAplus"));
			try
			{
				object obj = _cxsCase.InvokeAction("Top.appModelV8.Custom Actions", "GetIHapp");
				objConsole = bjacType.InvokeMember("CreateAppObjectForConsole", BindingFlags.InvokeMethod, null, mBJAC, new object[6]
				{
					EDRFile,
					tName,
					model,
					(short)2,
					obj,
					text
				});
				if (objConsole != null)
				{
					object obj2 = objConsole.GetType().InvokeMember("ATVService", BindingFlags.GetProperty, null, objConsole, new object[0]);
					if (obj2 != null)
					{
						restoreTasc = obj2.GetType().InvokeMember("XMLApp", BindingFlags.GetProperty, null, obj2, new object[0]) as string;
					}
				}
			}
			catch (Exception ex)
			{
				objConsole = null;
				ShowMessageBox(new ShowMessageBoxEventArgs
				{
					Message = "Error: " + ex.Message,
					Title = GetProductI18nName() + "-CreateAppObjectForConsole "
				});
				return IntPtr.Zero;
			}
			try
			{
				SizingHelper.passSpecToEDR(objConsole, this, text);
			}
			catch (Exception ex2)
			{
				ShowMessageBox(new ShowMessageBoxEventArgs
				{
					Message = "Error: " + ex2.Message,
					Title = GetProductI18nName() + "-SetATVVariables"
				});
			}
			return Marshal.GetIDispatchForObject(objConsole);
		}
	}
