		protected override void OnUpdateData()
		{
			base.OnUpdateData();
			if (base.IsInitialUpdate && sendReady)
			{
				sendReady = false;
				string text = ExpandDataPath("@main");
				base.UnityContainer.Parent.Parent.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ExchangerSizeEvent>().Subscribe(OnExchangerSize);
				base.UnityContainer.Parent.Parent.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ExchangerRevertEvent>().Subscribe(OnExchangerRevert);
				if (!exchangerEventHandlers.ContainsKey(text))
				{
					exchangerEventHandlers.Add(text, new List<MMHeatx_setup_specif_ViewModel>());
				}
				if (!exchangerEventHandlers[text].Contains(this))
				{
					exchangerEventHandlers[text].Add(this);
				}
				base.UnityContainer.Parent.Parent.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ExchangerReadyToSizeEvent>().Publish(new ExchangerSizeEventArgs
				{
					BlockPath = text
				});
			}
			if (base.IsInitialUpdate)
			{
				UpdatePrompt();
			}
		}

		public override void OnViewClosed()
		{
			base.UnityContainer.Parent.Parent.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ExchangerSizeEvent>().Unsubscribe(OnExchangerSize);
			base.UnityContainer.Parent.Parent.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ExchangerRevertEvent>().Unsubscribe(OnExchangerRevert);
			string key = ExpandDataPath("@main");
			if (exchangerEventHandlers.ContainsKey(key))
			{
				List<MMHeatx_setup_specif_ViewModel> list = exchangerEventHandlers[key];
				if (list.Contains(this))
				{
					list.Remove(this);
					if (list.Count == 0)
					{
						exchangerEventHandlers.Remove(key);
					}
				}
			}
			base.OnViewClosed();
		}

		private void OnExchangerRevert(ExchangerRevertEventArgs args)
		{
			if (isOnlyEvent(args.BlockPath))
			{
				if (args.TransferUA)
				{
					cmdReconcile_CommandExecute(null);
				}
				else if (args.TransferToShortCut)
				{
					ExpandDataPathAndSet("@main.Input.MODE", "value", "0", "SHORTCUT");
				}
			}
		}

		private void OnExchangerSize(ExchangerSizeEventArgs args)
		{
			if (!isOnlyEvent(args.BlockPath))
			{
				return;
			}
			if (args.DialogType == HeatXConvertRigorousDialogType.SizeExchanger)
			{
				string text = "";
				string modelName = string.Empty;
				string arg = ExpandDataPath("@main").Replace("Top.appModelV8.Blocks.", string.Empty).Replace("Data.Blocks.", string.Empty);
				if (args.ApplicationName.Equals("TASCPLUS-RIG", StringComparison.InvariantCultureIgnoreCase) || args.ApplicationName.Equals("KETTLE", StringComparison.InvariantCultureIgnoreCase) || args.ApplicationName.Equals("THERMOSIPHON", StringComparison.InvariantCultureIgnoreCase))
				{
					modelName = "Tasc";
					text = Resources.MMHeatx_setup_specif_ViewModel__CxvMultiMapOption_Display_Size_EDR_Shell_Tube;
				}
				if (args.ApplicationName.CompareTo("ACOL-RIG") == 0)
				{
					modelName = "Acol";
					text = Resources.MMHeatx_setup_specif_ViewModel__CxvMultiMapOption_Display_Size_EDR_AirCooled;
				}
				if (args.ApplicationName.CompareTo("APLE-RIG") == 0)
				{
					modelName = "Aple";
					text = "Size Plate";
				}
				if (!string.IsNullOrWhiteSpace(text))
				{
					text = $"{text} ({arg})";
				}
				ExecuteSize(text, modelName, args.TemplateFilePath, args.ApplicationName);
			}
			else if (args.DialogType == HeatXConvertRigorousDialogType.SpecifyExcahngerGeometry)
			{
				ConverttoGeometry(args.ImportFilePath, args.ImportEDR, args.ApplicationName, fromActivation: true);
			}
		}

		public void ExecuteSize(object parameter, string modelName, string templateFilePath, string modelTypeInAplus = "")
		{
			if (_cxsCase == null)
			{
				_cxsCase = base.UnityContainer.Resolve<CxsCase>(Array.Empty<ResolverOverride>());
			}
			int? num = _cxsCase.InvokeAction("Top.appModelV8.Custom Actions", "EnableHxSize") as int?;
			bool flag = true;
			if (string.IsNullOrEmpty(parameter as string))
			{
				parameter = CxsConverter.ValueToString(ExpandDataPathAndGet("@main", "id"));
			}
			if (num > 0)
			{
				string message;
				switch (num)
				{
				case 1:
				case 3:
					message = ApwnResources.FailStartEDR;
					break;
				case 2:
					message = string.Format(ApwnResources.BadEDRVersion, _cxsCase.InvokeAction("Top.appModelV8.Custom Actions", "BjacAPver").ToString());
					break;
				case 4:
					message = ApwnResources.MMHeatx_setup_specif_SizeRigorous_Noresults;
					break;
				case 5:
					message = ApwnResources.MMHeatx_setup_specif_SizeRigorous_Ineo;
					break;
				default:
					message = ApwnResources.MMHeatx_setup_specif_SizeRigorous_Errorcheck;
					break;
				}
				ShowMessageBox(new ShowMessageBoxEventArgs
				{
					Message = message,
					Title = GetProductI18nName() + " - " + parameter.ToString()
				});
				flag = false;
			}
			else if (num < 0)
			{
				string message2 = "";
				if (num.HasValue && num == -1)
				{
					message2 = ApwnResources.MMHeatx_setup_specif_SizeRigorous_Inputchanged;
				}
				ShowMessageBoxEventArgs e = new ShowMessageBoxEventArgs
				{
					Title = GetProductI18nName() + " - " + parameter.ToString(),
					MsgBoxButton = MessageBoxButton.OKCancel
				};
				e.Message = message2;
				ShowMessageBox(e);
				if (e.DialogResult == MessageBoxResult.Cancel)
				{
					flag = false;
				}
			}
			string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.MODE", "value"));
			if (flag)
			{
				DisplayForm(new DisplayFormEventArgs
				{
					HideCloseButton = true,
					ResizeMode = ResizeMode.CanResize,
					FormProgId = "MMHeatx.MMHeatx_setup_sizeRigorous",
					LegacyFlags = 0,
					ShortName = string.Format(Resources.EDRConsoleHeader, parameter as string),
					CompleteDataPaths = new string[1] { "SIZERIG" },
					Parameters = 
					{
						{
							"TEMPLATE",
							(object)templateFilePath
						},
						{
							"MODEL",
							(object)modelName
						},
						{
							"MODETypeAplus",
							(object)modelTypeInAplus
						}
					}
				});
				base.ResolvedCxsProvider.UpdateDataCache();
				if (base.View != null && text == CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.MODE", "value")))
				{
					(base.View as MMHeatx_setup_specif).UpdateOptionValue(text);
				}
			}
			else if (base.View != null)
			{
				(base.View as MMHeatx_setup_specif).UpdateOptionValue(text);
			}
		}

		private void cmdReconcile_CommandExecute(object parameter)
		{
			string units = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Output.HX_UA", "uom"));
			double? num = CxsConverter.ValueToDouble(ExpandDataPathAndGet("@main.Output.HX_UA", "value"));
			string units2 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Output.U-AVG-U-D", "uom"));
			double? num2 = CxsConverter.ValueToDouble(ExpandDataPathAndGet("@main.Output.U-AVG-U-D", "value"));
			string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.AREA", "value"));
			string text2 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.PROGRAM_MODE", "value"));
			double? num3 = CxsConverter.ValueToDouble(ExpandDataPathAndGet("@main.Output.HX_FMTD", "value"));
			string units3 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Output.HOT_PRES", "uom"));
			double? num4 = CxsConverter.ValueToDouble(ExpandDataPathAndGet("@main.Output.HOT_PRES", "value"));
			string units4 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Output.COLD_PRES", "uom"));
			double? num5 = CxsConverter.ValueToDouble(ExpandDataPathAndGet("@main.Output.COLD_PRES", "value"));
			if (text2 == "MAX-FOULING")
			{
				ShowMessageBox(new ShowMessageBoxEventArgs
				{
					Message = Resources.MMHeatx_setup_specif_ViewModel_MaxFouling_Error
				});
			}
			else
			{
				if (!num.HasValue || num == 0.0)
				{
					return;
				}
				if (text != null && text.Length != 0)
				{
					ShowMessageBoxEventArgs e = new ShowMessageBoxEventArgs
					{
						Message = Resources.MMHeatx_setup_specif_ViewModel_Delete_exchanger_area_spec,
						Title = Resources.MMHeatx_setup_specif_ViewModel_Delete_existing_area_spec,
						MsgBoxButton = MessageBoxButton.OKCancel
					};
					ShowMessageBox(e);
					if (e.DialogResult == MessageBoxResult.Cancel)
					{
						ShowMessageBoxEventArgs args = new ShowMessageBoxEventArgs
						{
							Message = Resources.MMHeatx_setup_specif_ViewModel_No_UA_transferred,
							Title = Resources.MMHeatx_setup_specif_ViewModel_Delete_existing_area_spec
						};
						ShowMessageBox(args);
						return;
					}
				}
				string text3 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.HDP_OPTION", "value"));
				string text4 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.CDP_OPTION", "value"));
				if (text != null && text.Length != 0)
				{
					ExpandDataPathAndSet("@main.Input.AREA", "value", null);
				}
				if (text3 == "GEOMETRY")
				{
					ExpandDataPathAndSet("@main.Input.HDP_OPTION", "value", "0", "CONSTANT");
				}
				if (text4 == "GEOMETRY")
				{
					ExpandDataPathAndSet("@main.Input.CDP_OPTION", "value", "0", "CONSTANT");
				}
				if (num4.HasValue && num4 != 0.0)
				{
					ExpandDataPathAndSet("@main.Input.PRES_HOT", "value", units3, num4);
				}
				if (num5.HasValue && num5 != 0.0)
				{
					ExpandDataPathAndSet("@main.Input.PRES_COLD", "value", units4, num5);
				}
				ExpandDataPathAndSet("@main.Input.UA", "value", units, num);
				ExpandDataPathAndSet("@main.Input.U_OPTION", "value", "0", "CONSTANT");
				if (num2.HasValue && num2 != 0.0)
				{
					ExpandDataPathAndSet("@main.Input.U", "value", units2, num2);
				}
				ExpandDataPathAndSet("@main.Input.MODE", "value", "0", "SHORTCUT");
				if (num3.HasValue && num3 > 1.0)
				{
					num3 = 1.0;
				}
				ExpandDataPathAndSet("@main.Input.LMTD_CORRECT", "value", "0", num3);
				CloseEDRBrowserScreen();
			}
		}

