		private void GetModelType(ref string type, ref string modelType, ref string modelName)
		{
			string path = ExpandDataPath("@main.Input.MODE");
			modelName = CxsConverter.ValueToString(base.ResolvedCxsProvider.BatchGet(path, "value", null));
			string arg = ExpandDataPath("@main").Replace("Top.appModelV8.Blocks.", string.Empty).Replace("Data.Blocks.", string.Empty);
			if (modelName == "TASCPLUS-RIG" || modelName == "KETTLE" || modelName == "THERMOSIPHON")
			{
				type = $"Size Shell&Tube ({arg})";
				modelType = "Tasc";
			}
			else if (modelName == "ACOL-RIG")
			{
				type = $"Size AirCooled ({arg})";
				modelType = "Acol";
			}
			else if (modelName == "APLE-RIG")
			{
				type = $"Size Plate ({arg})";
				modelType = "Aple";
			}
		}

