			base.OnSubPropertyDataChanged(pd, subPropertyName);
		}

		private void UpdatePrompt()
		{
			CxvBooleanPropertyData cxvBooleanPropertyData = DetailedOptionUsed as CxvBooleanPropertyData;
			if (cxvBooleanPropertyData.Value.HasValue && cxvBooleanPropertyData.Value.Value)
			{
				DetailedOptionPrompt = null;
			}
			else
			{
				DetailedOptionPrompt = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.CC Nodes.DETAIL", "description"));
			}
		}

		public string ModeSelection(string NewSelection)
		{
			base.ResolvedCxsProvider.UpdateDataCache();
			string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.MODE", "value"));
			string text2 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.INPUT_FILE", "value"));
			if ((string.IsNullOrEmpty(text2) || !File.Exists(text2)) && text.ToUpper() != NewSelection.ToUpper() && NewSelection.ToUpper() != "SHORTCUT")
			{
				short type = 0;
				if (NewSelection.ToUpper() == "TASCPLUS-RIG")
				{
					type = 1;
				}
				else if (NewSelection.ToUpper() == "KETTLE")
				{
					type = 2;
				}
				else if (NewSelection.ToUpper() == "THERMOSIPHON")
				{
					type = 3;
				}
				else if (NewSelection.ToUpper() == "ACOL-RIG")
				{
					type = 4;
				}
				else if (NewSelection.ToUpper() == "APLE-RIG")
				{
					type = 5;
				}
				EdrConvertRigorous edrConvertRigorous = new EdrConvertRigorous(type);
				if (edrConvertRigorous.ShowDialog() != true)
				{
					return text;
				}
				Convert(edrConvertRigorous);
			}
			else if (string.Equals(NewSelection, "SHORTCUT"))
			{
				CloseEDRBrowserScreen();
			}
			return "";
		}

		private void Convert(EdrConvertRigorous dlg)
		{
			int selectedExchangerType = dlg.SelectedExchangerType;
			string text = string.Empty;
			object obj = null;
			string modelName = string.Empty;
			string arg = ExpandDataPath("@main").Replace("Top.appModelV8.Blocks.", string.Empty).Replace("Data.Blocks.", string.Empty);
			switch (selectedExchangerType)
			{
			case 1:
				text = "TASCPLUS-RIG";
				obj = Resources.MMHeatx_setup_specif_ViewModel__CxvMultiMapOption_Display_Size_EDR_Shell_Tube;
				modelName = "Tasc";
				break;
			case 2:
				text = "KETTLE";
				obj = Resources.MMHeatx_setup_specif_ViewModel__CxvMultiMapOption_Display_Size_EDR_Shell_Tube;
				modelName = "Tasc";
				break;
			case 3:
				text = "THERMOSIPHON";
				obj = Resources.MMHeatx_setup_specif_ViewModel__CxvMultiMapOption_Display_Size_EDR_Shell_Tube;
				modelName = "Tasc";
				break;
			case 4:
				text = "ACOL-RIG";
				obj = Resources.MMHeatx_setup_specif_ViewModel__CxvMultiMapOption_Display_Size_EDR_AirCooled;
				modelName = "Acol";
				break;
			case 5:
				text = "APLE-RIG";
				obj = "Size Plate";
				modelName = "Aple";
				break;
			}
			if (!string.IsNullOrWhiteSpace(obj as string))
			{
				obj = $"{obj} ({arg})";
			}
			string edrFileName = dlg.EdrFileName;
			string templateFilePath = "";
			int selectedConvertMethod = dlg.SelectedConvertMethod;
			bool isSizeInterativelyUsingTemplate = dlg.IsSizeInterativelyUsingTemplate;
			bool isImportEDRFile = dlg.IsImportEDRFile;
			if (selectedConvertMethod == 2)
			{
				ConverttoGeometry(edrFileName, isImportEDRFile, text, fromActivation: true);
				return;
			}
			if (isSizeInterativelyUsingTemplate)
			{
				templateFilePath = dlg.TemplateFileName;
			}
			ExecuteSize(obj, modelName, templateFilePath, text);
		}

		private void ConverttoGeometry(string filename, bool edrFile, string strMode, bool fromActivation)
		{
			if (!edrFile && !CanSpecifyGeometry())
			{
				return;
			}
			if (fromActivation)
			{
				ExpandDataPathAndSet("@main.Input.SIZE_TEMPL", "value", "YES");
				bool num = base.ResolvedCxsProvider.BatchSet(ExpandDataPath("@main") + ".Input.MODE", "value", null, strMode);
				ExpandDataPathAndSet("@main.Input.SIZE_TEMPL", "value", "NO");
				if (!num)
				{
					return;
				}
			}
			if (edrFile)
			{
				ExpandDataPathAndSet("@main.Input.INPUT_FILE", "value", filename);
				ExpandDataPathAndSet("@main.Input.PROGRAM_MODE", "value", "SIMULATION");
				return;
			}
			string text = ".!EDR Browser";
			string text2 = ExpandDataPath("@main");
			text2 = ((!text2.Contains("Blocks")) ? text2.Replace("Top.appModelV8.", "") : text2.Replace("Data.", "").Substring(text2.IndexOf("Blocks")));
			text2 = text2 + "." + text.Substring(2);
			if (string.IsNullOrEmpty(filename))
			{
				filename = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.INPUT_FILE", "value"));
			}
			if (string.IsNullOrEmpty(filename) || !File.Exists(filename))
			{
				CreateEDRFile(ExpandDataPath("@main"), "", strMode);
			}
			DisplayOrReDisplayFormEventArgs payload = new DisplayOrReDisplayFormEventArgs
			{
				Path = text2,
				TabName = null,
				UseNewTab = false
			};
			((CompositePresentationEvent<DisplayOrReDisplayFormEventArgs>)(object)base.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<DisplayOrReDisplayFormEvent>()).Publish(payload);
		}

		private void CreateEDRFile(string basePath, string inputfilePath, string mode)
		{
			if (basePath != ExpandDataPath("@main"))
			{
				return;
			}
			if (_cxsCase == null)
			{
				_cxsCase = base.UnityContainer.Resolve<CxsCase>(Array.Empty<ResolverOverride>());
			}
			string tName = _cxsCase.CaseWorkingDirectory;
			inputfilePath = SizingHelper.createEDRFile(_cxsCase, basePath, ref tName);
			if (string.IsNullOrEmpty(inputfilePath) || string.IsNullOrEmpty(mode))
			{
				return;
			}
			string text = string.Empty;
			string variable = string.Empty;
			switch (mode)
			{
			case "TASCPLUS-RIG":
			case "KETTLE":
			case "THERMOSIPHON":
				text = "Tasc";
				variable = "TascProgMode";
				break;
			case "ACOL-RIG":
				text = "Acol";
				variable = "AcolProgMode";
				break;
			case "APLE-RIG":
				text = "Aple";
				variable = "PlateProgMode";
				break;
			}
			IAplusBJACWrapper aplusBJACWrapper = base.UnityContainer.Resolve<IAplusBJACWrapper>(Array.Empty<ResolverOverride>());
			_myBJAC = aplusBJACWrapper.BJACApp;
			if (_myBJAC == null)
			{
				return;
			}
			_bjacType = aplusBJACWrapper.ComType;
			try
			{
				if (_objATVApp == null)
				{
					_objATVApp = _bjacType.InvokeMember("CreateAppObject", BindingFlags.InvokeMethod, null, _myBJAC, new object[2] { inputfilePath, text });
				}
			}
			catch (Exception ex)
			{
				_objATVApp = null;
				ShowMessageBox(new ShowMessageBoxEventArgs
				{
					Message = "Error: " + ex.Message,
					Title = GetProductI18nName() + "-CreateAppObject "
				});
				return;
			}
			AppDomain.CurrentDomain.AssemblyResolve += currentDomain_AssemblyResolve;
			try
			{
				object obj = _cxsCase.InvokeAction("Top.appModelV8.Custom Actions", "GetIHapp");
				_bjacType.InvokeMember("ImportPFS", BindingFlags.InvokeMethod, null, _myBJAC, new object[5] { inputfilePath, tName, text, obj, mode });
			}
			catch (Exception ex2)
			{
				ShowMessageBox(new ShowMessageBoxEventArgs
				{
					Message = "Error: " + ex2.Message,
					Title = GetProductI18nName() + "-ImportPFS "
				});
			}
			AppDomain.CurrentDomain.AssemblyResolve -= currentDomain_AssemblyResolve;
			object pScalars = null;
			if (_objATVApp != null)
			{
				try
				{
					SizingHelper.setATVar(_objATVApp, ref pScalars, variable, "3");
					SizingHelper.passSpecToEDR(_objATVApp, this, mode);
				}
				catch (Exception ex3)
				{
					ShowMessageBox(new ShowMessageBoxEventArgs
					{
						Message = "Error: " + ex3.Message,
						Title = GetProductI18nName() + "-setATVariables "
					});
				}
			}
			if (pScalars != null)
			{
				pScalars = null;
			}
			_bjacType.InvokeMember("FileExport", BindingFlags.InvokeMethod, null, _myBJAC, new object[2] { inputfilePath, inputfilePath });
			string value = inputfilePath;
			string caseWorkingDirectory = _cxsCase.CaseWorkingDirectory;
			string text2 = inputfilePath.Substring(inputfilePath.LastIndexOf("\\") + 1);
			string value2 = caseWorkingDirectory + "\\" + text2;
			if (inputfilePath.Equals(value2, StringComparison.InvariantCultureIgnoreCase))
			{
				value = text2;
			}
			ExpandDataPathAndSet("@main.Input.INPUT_FILE", "value", value);
		}

		private Assembly currentDomain_AssemblyResolve(object sender, ResolveEventArgs args)
		{
			if (_alreadyTried.Contains(args.Name))
			{
				return null;
			}
			Assembly assembly = AppDomain.CurrentDomain.GetAssemblies().FirstOrDefault((Assembly x) => x.FullName == args.Name);
			if (assembly != null)
			{
				return assembly;
