		[DebuggerNonUserCode]
		[GeneratedCode("PresentationBuildTasks", "4.0.0.0")]
		[EditorBrowsable(EditorBrowsableState.Never)]
		void IComponentConnector.Connect(int connectionId, object target)
		{
			switch (connectionId)
			{
			case 1:
				fraEst = (MMGroupBox)target;
				break;
			case 2:
				lbtuT_est_label = (MMLabel)target;
				break;
			case 3:
				lbtuT_est = (MMVariableEdit)target;
				break;
			case 4:
				lbtuP_est_label = (MMLabel)target;
				break;
			case 5:
				lbtuP_est = (MMVariableEdit)target;
				break;
			case 6:
				fraFlashOp = (MMGroupBox)target;
				break;
			case 7:
				spnMaxit_label = (MMLabel)target;
				break;
			case 8:
				spnMaxit = (MMSpinBox)target;
				break;
			case 9:
				lbtuTol_label = (MMLabel)target;
				break;
			case 10:
				lbtuTol = (MMVariableEdit)target;
				break;
			default:
				_contentLoaded = true;
				break;
			}
		}
	}
