		public bool IsInletStreamConnectedWithoutOutStream
		{
			get
			{
				if (varHSDependencies != null)
				{
					varHSDependencies.PropertyDependencyChanged -= varHSDependencies_PropertyDependencyChangedHandler;
				}
				if (varHSDependencies != null)
				{
					varHSDependencies.Clear();
				}
				else
				{
					varHSDependencies = new CxvPropertyWatch();
				}
				int? num = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Ports.HS(IN)", "child_count", null, varHSDependencies));
				int? num2 = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Ports.HS(OUT)", "child_count", null, varHSDependencies));
				if (!varHSDependencies.IsEmpty)
				{
					varHSDependencies.PropertyDependencyChanged += varHSDependencies_PropertyDependencyChangedHandler;
				}
				else
				{
					varHSDependencies = null;
				}
				if (num.HasValue && num.Value > 0)
				{
					if (num2.HasValue)
					{
						return num2.Value == 0;
					}
					return true;
				}
				return false;
			}
		}

