		protected override void OnUpdateData()
		{
			if (base.IsInitialUpdate)
			{
				UpdateComboboxes();
			}
			base.OnUpdateData();
		}

		private void UpdateComboboxes()
		{
			if (varOptDependencies != null)
			{
				varOptDependencies.PropertyDependencyChanged -= varOptDependencies_PropertyDependencyChangedHandler;
			}
			if (varOptDependencies != null)
			{
				varOptDependencies.Clear();
			}
			else
			{
				varOptDependencies = new CxvPropertyWatch();
			}
			string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.SPEC_OPT", "value", null, varOptDependencies));
			_needUpdateVar = false;
			string text2 = CxsConverter.ValueToString(ResolveParameter("SpecOpt2"));
			switch (text)
			{
			case "TP":
				if (text2 == "Temperature")
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Pressure");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Temperature");
				}
				else
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Temperature");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Pressure");
				}
				break;
			case "TV":
				if (text2 == "Temperature")
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Vapor fraction");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Temperature");
				}
				else
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Temperature");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Vapor fraction");
				}
				break;
			case "TD":
				if (text2 == "Temperature")
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Duty");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Temperature");
				}
				else
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Temperature");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Duty");
				}
				break;
			case "TQ":
				if (text2 == "Temperature")
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Inlet heat stream");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Temperature");
				}
				else
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Temperature");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Inlet heat stream");
				}
				break;
			case "PV":
				if (text2 == "Pressure")
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Vapor fraction");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Pressure");
				}
				else
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Pressure");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Vapor fraction");
				}
				break;
			case "PD":
				if (text2 == "Pressure")
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Duty");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Pressure");
				}
				else
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Pressure");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Duty");
				}
				break;
			case "PQ":
				if (text2 == "Pressure")
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Inlet heat stream");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Pressure");
				}
				else
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Pressure");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Inlet heat stream");
				}
				break;
			}
			OnPropertyChanged("IsOpt2Enabled");
			_needUpdateVar = true;
			if (!varOptDependencies.IsEmpty)
			{
				varOptDependencies.PropertyDependencyChanged += varOptDependencies_PropertyDependencyChangedHandler;
			}
			else
			{
				varOptDependencies = null;
			}
		}

		protected override void OnSubPropertyDataChanged(CxvPropertyDeclaration pd, string subPropertyName)
		{
			if ((pd.Name == "cboSpecOpt_var1" || pd.Name == "cboSpecOpt_var2") && subPropertyName == "Value" && _needUpdateVar)
			{
				CxvAdvCollectionPropertyData cxvAdvCollectionPropertyData = cboSpecOpt_AdvCollection1 as CxvAdvCollectionPropertyData;
				CxvAdvCollectionPropertyData cxvAdvCollectionPropertyData2 = cboSpecOpt_AdvCollection2 as CxvAdvCollectionPropertyData;
				string text = null;
				if (cxvAdvCollectionPropertyData.SelectedItem == Resources.MMFlash3_Input_Specif_ViewModel__CxvSpecOption_Display_Temperature)
				{
					if (cxvAdvCollectionPropertyData2.SelectedItem == Resources.MMFlash3_Input_Specif_ViewModel__CxvSpecOption_Display_Pressure)
					{
						text = "TP";
					}
					else if (cxvAdvCollectionPropertyData2.SelectedItem == Resources.MMFlash3_Input_Specif_ViewModel__CxvSpecOption_Display_Inlet_heat_stream)
					{
						text = "TQ";
					}
					else if (cxvAdvCollectionPropertyData2.SelectedItem == Resources.MMFlash3_Input_Specif_ViewModel__CxvSpecOption_Display_Vapor_fraction)
					{
						text = "TV";
					}
					else if (cxvAdvCollectionPropertyData2.SelectedItem == Resources.MMFlash3_Input_Specif_ViewModel__CxvSpecOption_Display_Duty)
					{
						text = "TD";
					}
				}
				else if (cxvAdvCollectionPropertyData.SelectedItem == Resources.MMFlash3_Input_Specif_ViewModel__CxvSpecOption_Display_Pressure)
				{
					if (cxvAdvCollectionPropertyData2.SelectedItem == Resources.MMFlash3_Input_Specif_ViewModel__CxvSpecOption_Display_Temperature)
					{
						text = "TP";
					}
					else if (cxvAdvCollectionPropertyData2.SelectedItem == Resources.MMFlash3_Input_Specif_ViewModel__CxvSpecOption_Display_Inlet_heat_stream)
					{
						text = "PQ";
					}
					else if (cxvAdvCollectionPropertyData2.SelectedItem == Resources.MMFlash3_Input_Specif_ViewModel__CxvSpecOption_Display_Vapor_fraction)
					{
						text = "PV";
					}
					else if (cxvAdvCollectionPropertyData2.SelectedItem == Resources.MMFlash3_Input_Specif_ViewModel__CxvSpecOption_Display_Duty)
					{
						text = "PD";
					}
				}
				else if (cxvAdvCollectionPropertyData.SelectedItem == Resources.MMFlash3_Input_Specif_ViewModel__CxvSpecOption_Display_Duty)
				{
					if (cxvAdvCollectionPropertyData2.SelectedItem == Resources.MMFlash3_Input_Specif_ViewModel__CxvSpecOption_Display_Temperature)
					{
						text = "TD";
					}
					else if (cxvAdvCollectionPropertyData2.SelectedItem == Resources.MMFlash3_Input_Specif_ViewModel__CxvSpecOption_Display_Pressure)
					{
						text = "PD";
					}
				}
				else if (cxvAdvCollectionPropertyData.SelectedItem == Resources.MMFlash3_Input_Specif_ViewModel__CxvSpecOption_Display_Vapor_fraction)
				{
					if (cxvAdvCollectionPropertyData2.SelectedItem == Resources.MMFlash3_Input_Specif_ViewModel__CxvSpecOption_Display_Temperature)
					{
						text = "TV";
					}
					else if (cxvAdvCollectionPropertyData2.SelectedItem == Resources.MMFlash3_Input_Specif_ViewModel__CxvSpecOption_Display_Pressure)
					{
						text = "PV";
					}
				}
				string text2 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.SPEC_OPT", "value"));
				if (!string.IsNullOrEmpty(text) && text2 != text)
				{
					_needUpdateCombos = false;
					ExpandDataPathAndSet("@main.Input.SPEC_OPT", "value", text);
					_needUpdateCombos = true;
				}
			}
			base.OnSubPropertyDataChanged(pd, subPropertyName);
		}
	}
