		private void UpdateComboboxes()
		{
			if (varOptDependencies != null)
			{
				varOptDependencies.PropertyDependencyChanged -= varOptDependencies_PropertyDependencyChangedHandler;
			}
			if (varOptDependencies != null)
			{
				varOptDependencies.Clear();
			}
			else
			{
				varOptDependencies = new CxvPropertyWatch();
			}
			string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.SPEC_OPT", "value", null, varOptDependencies));
			_needUpdateVar = false;
			string text2 = CxsConverter.ValueToString(ResolveParameter("SpecOpt2"));
			switch (text)
			{
			case "TP":
				if (text2 == "Temperature")
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Pressure");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Temperature");
				}
				else
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Temperature");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Pressure");
				}
				break;
			case "TV":
				if (text2 == "Temperature")
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Vapor fraction");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Temperature");
				}
				else
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Temperature");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Vapor fraction");
				}
				break;
			case "TD":
				if (text2 == "Temperature")
				{
					ResolveUpdateViewPropertyPath("cbospecopt_var1.value", "Duty");
					ResolveUpdateViewPropertyPath("cbospecopt_var2.value", "Temperature");
				}
				else
				{
					ResolveUpdateViewPropertyPath("cbospecopt_var1.value", "Temperature");
					ResolveUpdateViewPropertyPath("cbospecopt_var2.value", "Duty");
				}
				break;
			case "TQ":
				if (text2 == "Temperature")
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Inlet heat stream");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Temperature");
				}
				else
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Temperature");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Inlet heat stream");
				}
				break;
			case "PV":
				if (text2 == "Pressure")
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Vapor fraction");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Pressure");
				}
				else
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Pressure");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Vapor fraction");
				}
				break;
			case "PD":
				if (text2 == "Pressure")
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Duty");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Pressure");
				}
				else
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Pressure");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Duty");
				}
				break;
			case "PQ":
				if (text2 == "Pressure")
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Inlet heat stream");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Pressure");
				}
				else
				{
					ResolveUpdateViewPropertyPath("cboSpecOpt_var1.Value", "Pressure");
					ResolveUpdateViewPropertyPath("cboSpecOpt_var2.Value", "Inlet heat stream");
				}
				break;
			}
			OnPropertyChanged("IsOpt2Enabled");
			_needUpdateVar = true;
			if (!varOptDependencies.IsEmpty)
			{
				varOptDependencies.PropertyDependencyChanged += varOptDependencies_PropertyDependencyChangedHandler;
			}
			else
