				{
					if (cxvAdvCollectionPropertyData2.SelectedItem == Resources.MMFlash2_Input_Specif_ViewModel__CxvSpecOption_Display_Temperature)
					{
						text = "TP";
					}
					else if (cxvAdvCollectionPropertyData2.SelectedItem == Resources.MMFlash2_Input_Specif_ViewModel__CxvSpecOption_Display_Inlet_heat_stream)
