				else if (cxvAdvCollectionPropertyData.SelectedItem == Resources.MMFlash2_Input_Specif_ViewModel__CxvSpecOption_Display_Duty)
				{
					if (cxvAdvCollectionPropertyData2.SelectedItem == Resources.MMFlash2_Input_Specif_ViewModel__CxvSpecOption_Display_Temperature)
					{
						text = "TD";
